-- store/_retired/zhTW.lua
-- Traditional Chinese translations for phrases no addon in the family currently uses.
--
-- NOT dead. A phrase lands here when the last addon using it drops or rewords it,
-- and scan.py moves it straight back into store/zhTW.lua the moment any addon
-- starts using that exact English key again. Everything Quests v1.38.0 moved 224
-- phrases to EQ Objective Tracker in one release - this is what stops that costing
-- a translation.
--
-- Nothing here reaches the game. There is no reason to translate anything in this
-- file, and no reason to delete anything from it either.

local L = {}

L["%d hidden entries restored."] = "%d 條隱藏記錄已恢復。"
L["%d spells tracked. \"Default\" follows this category's Defaults tab; the last column flags a spell Important or Pinned."] = "已追蹤 %d 個法術。【預設】跟隨該分類的【預設值】標籤頁，最後一欄用於將法術標記為【重要】或【固定】。"
L["%s  \194\183  %s quests  \194\183  %s  \194\183  %s XP"] = "%s  •  %s 個任務  •  %s  •  %s 經驗"
L["%s Defaults"] = "%s 預設值"
L["%s%s|r %s(%s)|r%s  \226\128\148  %s%d|r in progress  %s%d|r banked  %s%d|r done  %s%d|r left"] = "%s%s|r %s(%s)|r%s  —  進行中 %s%d|r  已囤積 %s%d|r  已完成 %s%d|r  剩餘 %s%d|r"
L["/eqs\n/everythingquests\n\n|cff999999Both open this options window.|r\n\n/eqs whatsnew\n\n|cff999999Show what's new in the latest update.|r\n\n/eqs session\n\n|cff999999Show a recap of your current play session.|r"] = "/eqs\n/everythingquests\n\n|cff999999以上兩條命令均可打開此設置視窗。|r\n\n/eqs whatsnew\n\n|cff999999查看本次更新的新內容。|r\n\n/eqs session\n\n|cff999999查看當前遊戲會話統計。|r"
